import{o as e,s as t}from"./index-AEnKaG9l.js";import{t as n}from"./firma-BM6gEF1c.js";var r={"[OPERATOR PŁATNOŚCI]":`operator_nazwa`,"[ADRES OPERATORA]":`operator_adres`,"[BLIK, Przelewy24, karta płatnicza]":`metody`,"[24]":`przelozenie_h`,"[DATA WEJŚCIA W ŻYCIE]":`data_od`,"[DOSTAWCA POCZTY]":`poczta`,"[NAZWA, np. MailerLite]":`newsletter`,"[NAZWA]":`biuro`};function i(e,t={}){if(e==null)return e;let n=String(e);for(let[e,i]of Object.entries(r))t[i]&&(n=n.split(e).join(t[i]));return n}var a={operator_nazwa:`PayU S.A.`,operator_adres:`ul. Grunwaldzka 186, 60-166 Poznań`},o=e=>e?new Date(e+`T12:00:00`).toLocaleDateString(`pl-PL`,{day:`numeric`,month:`long`,year:`numeric`}):null,s={title:`Regulamin serwisu i sklepu exmortis.pl`,sections:[{id:`p1`,title:`§1. Kim jesteśmy i czego dotyczy regulamin`,body:[`1. Serwis exmortis.pl (dalej: „Serwis”) prowadzi [IMIĘ I NAZWISKO], prowadzący(-a) działalność gospodarczą pod firmą [NAZWA FIRMY], adres: [ADRES DZIAŁALNOŚCI], NIP: [NIP], REGON: [REGON], wpisany(-a) do Centralnej Ewidencji i Informacji o Działalności Gospodarczej (dalej: „Sprzedawca” albo „Usługodawca”).`,`2. Kontakt: e-mail [E-MAIL KONTAKTOWY], adres do korespondencji: [ADRES DO KORESPONDENCJI].`,`Telefon: [TELEFON] — opłata wg taryfy operatora.`,`3. Regulamin określa zasady korzystania z Serwisu, zakładania i prowadzenia Konta, korzystania z bezpłatnych usług elektronicznych, zakupu Treści cyfrowych i usług mentoringowych, udziału w Wydarzeniach online oraz tryb reklamacji i odstąpienia od umowy. Jest regulaminem w rozumieniu ustawy o świadczeniu usług drogą elektroniczną.`,`4. Regulamin jest dostępny bezpłatnie na stronie exmortis.pl/regulamin w sposób umożliwiający jego pobranie, utrwalenie i wydrukowanie.`]},{id:`p2`,title:`§2. Definicje`,body:[`1. Klient — osoba fizyczna, osoba prawna albo jednostka organizacyjna posiadająca zdolność prawną, która korzysta z Serwisu lub zawiera umowę ze Sprzedawcą.`,`2. Konsument — Klient będący osobą fizyczną, zawierający umowę niezwiązaną bezpośrednio z jego działalnością gospodarczą lub zawodową.`,`3. Przedsiębiorca na prawach konsumenta — osoba fizyczna zawierająca umowę bezpośrednio związaną z jej działalnością gospodarczą, gdy z treści umowy wynika, że nie ma ona dla niej charakteru zawodowego, wynikającego w szczególności z przedmiotu wykonywanej działalności (dane z CEIDG). Przysługują jej uprawnienia opisane w §9 i §12 w zakresie przewidzianym przepisami.`,`4. Konto — indywidualny panel Klienta w Serwisie, chroniony e-mailem i hasłem.`,`5. Treści cyfrowe — dane wytwarzane i dostarczane w postaci cyfrowej, w szczególności pliki PDF, nagrania audio, filmy i kursy wideo dostępne w Koncie.`,`6. Kurs wideo — Treść cyfrowa składająca się z lekcji (nagrań wideo z materiałami), udostępniana w Koncie przez określony czas.`,`7. Usługi mentoringowe — odpłatne usługi świadczone przez Sprzedawcę osobiście, w szczególności „Rozmowa na progu” i program „POWRÓT”.`,`8. Wydarzenie — spotkanie online (np. webinar, „Wieczór powrotu”, transmisja na żywo).`,`9. Usługi elektroniczne — usługi świadczone bezpłatnie drogą elektroniczną: Konto, newsletter „Listy powrotu”, test „Która śmierć jest Twoja?”, Minutnik ciszy, udostępnianie bezpłatnych materiałów, zapisy na Wydarzenia.`,`10. Skarbiec — część Serwisu z ofertą produktów i usług.`,`11. Zamówienie — oświadczenie woli Klienta zmierzające do zawarcia umowy sprzedaży Treści cyfrowych lub umowy o świadczenie Usługi mentoringowej.`]},{id:`p3`,title:`§3. Wymagania techniczne i bezpieczeństwo`,body:[`1. Do korzystania z Serwisu potrzebne są: urządzenie z dostępem do internetu, aktualna przeglądarka (np. Chrome, Firefox, Safari, Edge) z włączoną obsługą JavaScript i plików cookies niezbędnych do działania Serwisu, aktywny adres e-mail; do odtwarzania wideo — łącze o przepustowości co najmniej ok. 5 Mb/s; do plików PDF — program do ich odczytu; do Wydarzeń — aplikacja lub przeglądarka obsługująca Zoom.`,`2. Korzystanie z internetu wiąże się z ryzykami (np. złośliwe oprogramowanie, phishing, przejęcie hasła). Klient powinien chronić hasło, nie udostępniać go innym i korzystać z aktualnego oprogramowania. Sprzedawca nigdy nie prosi o podanie hasła e-mailem ani telefonicznie.`,`3. Klient nie może dostarczać treści o charakterze bezprawnym ani podejmować działań zakłócających działanie Serwisu.`]},{id:`p4`,title:`§4. Charakter usług — ważne zastrzeżenie`,body:[`1. Usługi i treści exmortis mają charakter mentoringowy i rozwojowy. NIE są psychoterapią, leczeniem, diagnozą, poradnictwem medycznym, psychologicznym, prawnym ani finansowym i nie zastępują pomocy specjalisty ani posługi duszpasterskiej.`,`2. Jeśli Klient jest w kryzysie psychicznym, ma myśli samobójcze albo jego życie lub zdrowie jest zagrożone, powinien niezwłocznie skontaktować się z numerem alarmowym 112, Telefonem Zaufania dla Dorosłych 116 123 lub Centrum Wsparcia 800 70 2222 (bezpłatnie, całą dobę) albo z lekarzem.`,`3. Usługi są przeznaczone wyłącznie dla osób pełnoletnich.`,`4. Sprzedawca może odmówić zawarcia umowy o Usługę mentoringową lub zaproponować jej przerwanie, jeśli w rozmowie kwalifikacyjnej lub w trakcie współpracy uzna, że Klient potrzebuje w pierwszej kolejności pomocy specjalisty. W razie przerwania z tej przyczyny Klient otrzymuje zwrot za niewykorzystaną część usługi.`]},{id:`p5`,title:`§5. Bezpłatne Usługi elektroniczne`,body:[`1. Umowa o Usługę elektroniczną zostaje zawarta z chwilą rozpoczęcia korzystania z niej (np. wysłania formularza zapisu, uruchomienia Minutnika), na czas nieoznaczony, a w przypadku usług jednorazowych (np. pobranie bezpłatnego PDF) — na czas jej wykonania.`,`2. Newsletter „Listy powrotu” wysyłany jest na podstawie zgody, po potwierdzeniu zapisu linkiem. Klient może wypisać się w każdej chwili, bez kosztów, linkiem w każdym e-mailu.`,`3. Klient może w każdej chwili, bez podania przyczyny i bez kosztów, rozwiązać umowę o Usługę elektroniczną (np. wypisać się, usunąć Konto).`,`4. Usługodawca może rozwiązać umowę o bezpłatną Usługę elektroniczną z zachowaniem 14-dniowego okresu wypowiedzenia z ważnych przyczyn (np. trwałe zakończenie świadczenia usługi, rażące naruszenie Regulaminu), informując o tym e-mailem. Rozwiązanie nie wpływa na dostęp do opłaconych Treści cyfrowych w okresie dostępu.`]},{id:`p6`,title:`§6. Konto`,body:[`1. Założenie Konta jest bezpłatne i wymaga podania imienia, e-maila, hasła, potwierdzenia pełnoletności i akceptacji Regulaminu. Konto może zostać założone także automatycznie przy pierwszym zakupie — wtedy Klient otrzymuje e-mail z linkiem do ustawienia hasła.`,`2. Konto jest osobiste. Zabronione jest udostępnianie Konta i danych logowania innym osobom.`,`3. Treści cyfrowe można odtwarzać jednocześnie na jednym urządzeniu; w okresie 30 dni z Konta można korzystać na maksymalnie 3 urządzeniach (listą urządzeń Klient zarządza w ustawieniach Konta).`,`4. W razie uzasadnionego podejrzenia udostępniania Konta lub naruszenia licencji (§8) system może automatycznie wstrzymać odtwarzanie wideo na 24 godziny. Klient zostaje o tym poinformowany i może się odwołać e-mailem — decyzję o dalszym postępowaniu podejmuje człowiek (Sprzedawca), nie system.`,`5. Klient może usunąć Konto w każdej chwili w ustawieniach Konta. Usunięcie Konta oznacza utratę dostępu do Treści cyfrowych udostępnianych w Koncie — przed usunięciem warto pobrać pliki PDF i audio.`]},{id:`p7`,title:`§7. Zamówienia, ceny i płatności`,body:[`1. Informacje w Serwisie nie stanowią oferty w rozumieniu Kodeksu cywilnego, lecz zaproszenie do zawarcia umowy.`,`2. Ceny podawane są w złotych polskich i są cenami brutto ([WYBIERZ JEDNO: „zawierają podatek VAT” — jeśli jesteś czynnym podatnikiem VAT / „Sprzedawca korzysta ze zwolnienia podmiotowego z VAT na podstawie art. 113 ust. 1 ustawy o VAT” — jeśli korzystasz ze zwolnienia]). Przy obniżce ceny Sprzedawca podaje także najniższą cenę z 30 dni przed wprowadzeniem obniżki.`,`3. Ceny mogą się zmieniać w czasie (np. cena premierowa). Wiążąca jest cena widoczna w podsumowaniu Zamówienia w chwili jego złożenia. Kody rabatowe mają warunki podane przy ich udostępnieniu; nie łączą się, chyba że zaznaczono inaczej.`,`4. Aby złożyć Zamówienie, Klient wybiera produkt, podaje dane, akceptuje Regulamin, składa wymagane oświadczenia (§9) i klika przycisk „Zamawiam z obowiązkiem zapłaty”. Umowa zostaje zawarta z chwilą otrzymania przez Klienta e-maila z potwierdzeniem Zamówienia, wysłanego po zaksięgowaniu płatności.`,`5. Płatności obsługuje [OPERATOR PŁATNOŚCI] ([ADRES OPERATORA]). Dostępne metody: [BLIK, Przelewy24, karta płatnicza]. Płatność jest jednorazowa i z góry.`,`6. Potwierdzenie zawarcia umowy, treść Regulaminu w wersji z dnia Zamówienia i wzór formularza odstąpienia Klient otrzymuje e-mailem (trwały nośnik) i może je pobrać w Koncie.`,`7. Dokument sprzedaży: [OPIS — np. „na życzenie Klienta wystawiamy fakturę / rachunek; dane do faktury można podać w Zamówieniu”].`]},{id:`p8`,title:`§8. Treści cyfrowe, okres dostępu i licencja`,body:[`1. Treści cyfrowe dostarczane są niezwłocznie po zaksięgowaniu płatności — przez udostępnienie ich w Koncie (zakładka „Moje produkty”) oraz, w przypadku niektórych plików, e-mailem.`,`2. Okres dostępu:`,`a) pliki PDF i audio — bez ograniczenia czasowego, dopóki Serwis jest prowadzony; Klient może je pobrać i zachować. W razie zamknięcia Serwisu Sprzedawca uprzedzi Klientów e-mailem co najmniej 30 dni wcześniej, aby mogli pobrać pliki;`,`b) filmy i Kursy wideo — 12 miesięcy od dnia zaksięgowania płatności (do końca tego dnia), chyba że w opisie produktu wskazano inaczej. Okres dostępu jest podawany przed zakupem, w potwierdzeniu Zamówienia i w Koncie.`,`c) Po upływie okresu dostępu Klient może — jeśli Sprzedawca to oferuje — przedłużyć dostęp na warunkach podanych w Koncie. Postęp w kursie pozostaje zapisany.`,`3. Kurs wideo może być udostępniany stopniowo (np. kolejna lekcja co 7 dni) — harmonogram jest podany w opisie produktu.`,`4. Pliki PDF są personalizowane: każda strona zawiera adres e-mail użyty przy zakupie, numer Zamówienia i datę, a pliki zawierają niewidoczne znaczniki identyfikujące licencję. Filmy wyświetlają znak wodny z adresem e-mail Klienta i identyfikatorem licencji.`,`5. Licencja: z chwilą dostarczenia Klient otrzymuje niewyłączną, niezbywalną, osobistą licencję na korzystanie z Treści cyfrowych na własny użytek, na terytorium całego świata, w okresie dostępu (dla PDF i audio — bez ograniczenia czasowego), z możliwością wydrukowania materiałów na własne potrzeby. Licencja nie obejmuje: udostępniania Treści cyfrowych lub Konta innym osobom, rozpowszechniania, publikowania w internecie, odsprzedaży, nagrywania i kopiowania filmów, usuwania oznaczeń licencji ani wykorzystywania treści w celach komercyjnych (np. w szkoleniach, coachingu, mentoringu prowadzonym przez Klienta) — z zastrzeżeniem dozwolonego użytku osobistego w granicach przewidzianych prawem autorskim.`,`6. Naruszenie licencji może skutkować wstrzymaniem dostępu (§6 ust. 4), a w razie rażącego lub powtarzającego się naruszenia — wypowiedzeniem umowy przez Sprzedawcę po bezskutecznym wezwaniu do zaprzestania naruszeń, bez wpływu na odpowiedzialność wynikającą z prawa autorskiego.`,`7. Wszelkie prawa do Serwisu, nazwy i znaku „exmortis”, tekstów, nagrań, grafik i materiałów przysługują Sprzedawcy lub podmiotom, które udzieliły mu licencji.`]},{id:`p9`,title:`§9. Prawo odstąpienia od umowy (Konsument i Przedsiębiorca na prawach konsumenta)`,body:[`1. Konsument może odstąpić od umowy zawartej na odległość w terminie 14 dni bez podania przyczyny i bez ponoszenia kosztów, z wyjątkiem kosztów wskazanych w ust. 6. Termin biegnie od dnia zawarcia umowy.`,`2. Aby odstąpić, wystarczy przed upływem terminu wysłać oświadczenie: przez funkcję „Odstąp od umowy tutaj” w Koncie lub na stronie exmortis.pl/odstapienie, e-mailem na [E-MAIL KONTAKTOWY] albo pocztą na [ADRES DO KORESPONDENCJI]. Można skorzystać ze wzoru formularza (Załącznik nr 1), ale nie jest to obowiązkowe. Sprzedawca niezwłocznie potwierdza otrzymanie oświadczenia e-mailem.`,`3. Sprzedawca zwraca wszystkie płatności niezwłocznie, nie później niż w 14 dni od otrzymania oświadczenia, tym samym sposobem płatności, którego użył Konsument, chyba że Konsument zgodzi się na inny sposób niewiążący się dla niego z kosztami.`,`4. TREŚCI CYFROWE (PDF, audio, wideo, Kursy wideo): prawo odstąpienia NIE przysługuje, jeżeli Sprzedawca rozpoczął dostarczanie Treści cyfrowych za wyraźną i uprzednią zgodą Konsumenta, który został poinformowany przed rozpoczęciem świadczenia, że po spełnieniu świadczenia utraci prawo odstąpienia, przyjął to do wiadomości, a Sprzedawca przekazał mu potwierdzenie (e-mail z potwierdzeniem Zamówienia). Bez takiej zgody Treści cyfrowe nie są udostępniane przed upływem 14 dni.`,`5. USŁUGI MENTORINGOWE: jeśli Konsument zażąda rozpoczęcia usługi przed upływem terminu na odstąpienie, a następnie odstąpi od umowy, zapłaci za świadczenia spełnione do chwili odstąpienia (proporcjonalnie do zakresu wykonanej usługi). Prawo odstąpienia nie przysługuje w odniesieniu do usługi wykonanej w pełni, jeśli Sprzedawca wykonał ją za wyraźną i uprzednią zgodą Konsumenta, który został poinformowany przed rozpoczęciem świadczenia, że po jego spełnieniu utraci prawo odstąpienia, i przyjął to do wiadomości.`,`6. Program „POWRÓT” jest zawierany na podstawie odrębnej umowy, która może przewidywać dodatkowe, korzystniejsze dla Klienta uprawnienia (np. gwarancję po pierwszej sesji); w pozostałym zakresie stosuje się niniejszy paragraf.`,`7. Postanowienia tego paragrafu stosuje się do Przedsiębiorcy na prawach konsumenta.`]},{id:`p10`,title:`§10. Usługi mentoringowe`,body:[`1. Zakres, czas trwania, liczba spotkań, cena i harmonogram Usługi mentoringowej są opisane na stronie produktu, a dla programu „POWRÓT” — w umowie zawieranej po rozmowie kwalifikacyjnej.`,`2. Spotkania odbywają się online (Zoom) lub w innym ustalonym miejscu. Klient może przełożyć spotkanie bez kosztów najpóźniej [24] godziny przed jego rozpoczęciem. Nieobecność bez wcześniejszej informacji oznacza wykorzystanie spotkania, chyba że wynikła z przyczyn niezależnych od Klienta (np. nagła choroba) — wtedy termin ustala się ponownie.`,`3. Sprzedawca może przełożyć spotkanie z ważnych przyczyn, proponując nowy termin; jeśli Klient go nie przyjmie, otrzymuje zwrot za to spotkanie.`,`4. Spotkania nie są nagrywane, chyba że obie strony wyraźnie się na to zgodzą. Treść rozmów jest poufna — Sprzedawca nie ujawnia jej osobom trzecim, z wyjątkiem sytuacji bezpośredniego zagrożenia życia lub zdrowia Klienta albo innych osób oraz obowiązków wynikających z przepisów prawa.`]},{id:`p11`,title:`§11. Wydarzenia online`,body:[`1. Udział w bezpłatnych Wydarzeniach wymaga zapisu (chyba że zapisy są wyłączone, np. transmisja na żywo). Link do spotkania jest osobisty — nie należy go udostępniać.`,`2. Uczestnik może mieć wyłączoną kamerę i mikrofon. Jeśli Wydarzenie jest nagrywane, informacja o tym jest podana na stronie Wydarzenia i przypomniana na jego początku; nagrywany jest obraz i dźwięk prowadzącego oraz osób, które same włączą kamerę lub mikrofon albo zadadzą pytanie głosowo. Pytania na czacie mogą być odczytywane bez podawania nazwiska.`,`3. Zabronione jest nagrywanie Wydarzeń przez uczestników, zakłócanie ich przebiegu oraz publikowanie treści obraźliwych lub bezprawnych. Sprzedawca może usunąć z Wydarzenia osobę naruszającą te zasady.`,`4. Sprzedawca może odwołać lub przełożyć Wydarzenie, informując zapisanych e-mailem.`]},{id:`p12`,title:`§12. Zgodność z umową i reklamacje`,body:[`1. Sprzedawca odpowiada wobec Konsumenta i Przedsiębiorcy na prawach konsumenta za zgodność Treści cyfrowych i usług z umową na zasadach określonych w ustawie o prawach konsumenta (w szczególności w rozdziale dotyczącym treści cyfrowych i usług cyfrowych) i w Kodeksie cywilnym.`,`2. W razie braku zgodności z umową Klient może żądać doprowadzenia do zgodności (np. naprawy pliku, przywrócenia dostępu), a gdy nie jest to możliwe lub nie nastąpi w rozsądnym czasie — obniżenia ceny albo odstąpienia od umowy, na zasadach określonych w przepisach.`,`3. Reklamację można złożyć formularzem w Koncie lub na stronie Kontakt, e-mailem na [E-MAIL KONTAKTOWY] albo pocztą. Warto opisać problem, wskazać numer Zamówienia i swoje żądanie.`,`4. Sprzedawca odpowiada na reklamację w ciągu 14 dni od jej otrzymania, e-mailem lub w inny wskazany przez Klienta sposób.`,`5. Wobec Klientów niebędących Konsumentami ani Przedsiębiorcami na prawach konsumenta odpowiedzialność Sprzedawcy z tytułu rękojmi jest wyłączona, a odpowiedzialność odszkodowawcza ograniczona do wysokości zapłaconej ceny, w granicach dopuszczalnych przez prawo.`,`6. Postanowienia Regulaminu nie wyłączają ani nie ograniczają praw Konsumentów wynikających z bezwzględnie obowiązujących przepisów.`]},{id:`p13`,title:`§13. Pozasądowe rozwiązywanie sporów`,body:[`Konsument może skorzystać z pomocy powiatowego (miejskiego) rzecznika konsumentów, organizacji konsumenckich lub z postępowania przed stałym polubownym sądem konsumenckim przy wojewódzkim inspektoracie Inspekcji Handlowej oraz z mediacji. Informacje: www.uokik.gov.pl. Udział Sprzedawcy w pozasądowym postępowaniu jest dobrowolny.`]},{id:`p14`,title:`§14. Dane osobowe`,body:[`Zasady przetwarzania danych osobowych opisuje Polityka prywatności (exmortis.pl/polityka-prywatnosci), a zasady plików cookies — Polityka cookies.`]},{id:`p15`,title:`§15. Zmiany Regulaminu`,body:[`1. Sprzedawca może zmienić Regulamin z ważnych przyczyn: zmiany przepisów prawa, decyzji lub orzeczeń organów, zmiany zakresu lub sposobu świadczenia usług, zmiany metod płatności, konieczności zapewnienia bezpieczeństwa lub przeciwdziałania nadużyciom, zmian redakcyjnych.`,`2. O zmianie posiadacze Kont i subskrybenci są informowani e-mailem co najmniej 14 dni przed jej wejściem w życie. Klient, który nie akceptuje zmian, może przed tą datą rozwiązać umowę o Usługi elektroniczne bez kosztów.`,`3. Do umów zawartych przed zmianą stosuje się Regulamin w brzmieniu z dnia zawarcia umowy, chyba że zmiana jest korzystniejsza dla Klienta.`]},{id:`p16`,title:`§16. Postanowienia końcowe`,body:[`1. Regulamin podlega prawu polskiemu. Wybór prawa nie pozbawia Konsumenta ochrony przysługującej mu na podstawie bezwzględnie obowiązujących przepisów państwa jego zwykłego pobytu.`,`2. Spory z Konsumentami rozstrzygają sądy właściwe według przepisów ogólnych; spory z pozostałymi Klientami — sąd właściwy dla siedziby Sprzedawcy.`,`3. Regulamin obowiązuje od [DATA WEJŚCIA W ŻYCIE].`]}]},c={id:`zalacznik-1`,title:`Załącznik nr 1 — Wzór formularza odstąpienia od umowy`,body:[`(formularz należy wypełnić i odesłać tylko w przypadku chęci odstąpienia od umowy)`,`Adresat: [NAZWA FIRMY], [ADRES DO KORESPONDENCJI], e-mail: [E-MAIL KONTAKTOWY]`,`Ja/My(*) niniejszym informuję/informujemy(*) o moim/naszym(*) odstąpieniu od umowy sprzedaży następujących rzeczy(*) / umowy dostawy następujących rzeczy(*) / umowy o dzieło polegającej na wykonaniu następujących rzeczy(*) / o świadczenie następującej usługi(*) / o dostarczanie treści cyfrowych(*):`,`………………………………………`,`Data zawarcia umowy(*) / odbioru(*): ………………`,`Numer zamówienia: ………………`,`Imię i nazwisko konsumenta(-ów): ………………`,`Adres konsumenta(-ów): ………………`,`Adres e-mail użyty przy zamówieniu: ………………`,`Podpis konsumenta(-ów) (tylko jeżeli formularz jest przesyłany w wersji papierowej): ………………`,`Data: ………………`,`(*) Niepotrzebne skreślić.`]},l={title:`Polityka prywatności exmortis.pl`,version:`1.1`,sections:[{id:`p1`,title:`§1. Administrator`,body:[`1. Administratorem Twoich danych osobowych jest [IMIĘ I NAZWISKO], prowadzący(-a) działalność gospodarczą pod firmą [NAZWA FIRMY], adres: [ADRES DZIAŁALNOŚCI], NIP: [NIP] (dalej: „Administrator”, „my”).`,`2. Kontakt w sprawach danych osobowych: [E-MAIL KONTAKTOWY] lub pocztą na [ADRES DO KORESPONDENCJI]. Nie wyznaczyliśmy inspektora ochrony danych.`]},{id:`p2`,title:`§2. Najważniejsze zasady`,body:[`Zbieramy tylko dane, których potrzebujemy. Nie sprzedajemy danych. Nie wysyłamy reklam bez Twojej zgody. Odpowiedzi z testu i treści rozmów mentoringowych traktujemy jako szczególnie wrażliwe — przetwarzamy je wyłącznie za Twoją wyraźną zgodą i nigdy nie przekazujemy do celów reklamowych.`]},{id:`p3`,title:`§3. Cele, podstawy prawne i okres przechowywania`,body:[`1. Konto w Serwisie — imię, e-mail, hasło (zaszyfrowane), ustawienia, urządzenia. Podstawa: wykonanie umowy o prowadzenie Konta (art. 6 ust. 1 lit. b RODO). Okres: do usunięcia Konta; Konta bez zakupów nieaktywne przez 3 lata usuwamy po wcześniejszym uprzedzeniu e-mailem.`,`2. Sprzedaż Treści cyfrowych i usług — dane z Zamówienia (imię, e-mail, dane do faktury, produkt, kwota, zgody). Podstawa: wykonanie umowy (art. 6 ust. 1 lit. b), a w zakresie rozliczeń — obowiązek prawny (art. 6 ust. 1 lit. c RODO, przepisy podatkowe i o rachunkowości). Okres: przez czas trwania umowy i dostępu, a dane rozliczeniowe — 5 lat od końca roku kalendarzowego, w którym upłynął termin płatności podatku.`,`3. Reklamacje, odstąpienia, obsługa korespondencji — Podstawa: obowiązek prawny (art. 6 ust. 1 lit. c) oraz nasz prawnie uzasadniony interes w odpowiadaniu na wiadomości (art. 6 ust. 1 lit. f). Okres: do zakończenia sprawy, a następnie do upływu terminu przedawnienia roszczeń.`,`4. Newsletter „Listy powrotu” — e-mail, imię, data i treść zgody, informacja o otwarciach i kliknięciach, źródło zapisu. Podstawa: Twoja zgoda (art. 6 ust. 1 lit. a RODO) oraz zgoda na otrzymywanie informacji handlowych e-mailem (art. 398 Prawa komunikacji elektronicznej). Zapis staje się aktywny dopiero po kliknięciu linku potwierdzającego, który wysyłamy e-mailem; datę kliknięcia zapisujemy jako datę zgody. Okres: do wycofania zgody (wypisania się); niepotwierdzone zapisy usuwamy po 7 dniach.`,`5. Test „Która śmierć jest Twoja?” — wynik testu widzisz bez podawania danych. Jeśli podasz e-mail, aby otrzymać wynik i dopasowane treści, przetwarzamy e-mail i wynik testu (bez Twoich odpowiedzi). Ponieważ wynik może wiązać się z informacjami o Twoim samopoczuciu lub zdrowiu, podstawą jest Twoja wyraźna zgoda (art. 6 ust. 1 lit. a i art. 9 ust. 2 lit. a RODO). Okres: 12 miesięcy od wypełnienia testu albo do wycofania zgody, zależnie od tego, co nastąpi wcześniej; po tym czasie wynik usuwamy automatycznie. Wyniku nie przekazujemy do celów reklamowych (np. Meta).`,`6. Bezpłatne materiały (PDF) — e-mail. Podstawa: zgoda / wykonanie umowy o usługę elektroniczną (art. 6 ust. 1 lit. a i b). Okres: do wysyłki materiału i rozpatrzenia ewentualnych reklamacji; jeśli zapiszesz się też na Listy powrotu — jak w ust. 4.`,`7. Wydarzenia online (webinary, „Wieczory powrotu”) — imię, e-mail, obecność, pytania; w razie nagrywania — wizerunek i głos, jeśli sam(a) włączysz kamerę lub mikrofon. Podstawa: wykonanie umowy (art. 6 ust. 1 lit. b), a w zakresie nagrania — nasz prawnie uzasadniony interes w udostępnieniu nagrania uczestnikom (art. 6 ust. 1 lit. f) i Twoja decyzja o włączeniu kamery/mikrofonu. Okres: dane zapisu — 90 dni po spotkaniu; nagranie — przez okres jego udostępnienia (podany przy wydarzeniu).`,`8. Usługi mentoringowe (Rozmowa na progu, POWRÓT) i formularze kwalifikacyjne — dane kontaktowe, terminy, notatki ze spotkań, informacje, które sam(a) przekażesz, w tym dotyczące zdrowia, samopoczucia, przekonań religijnych lub światopoglądowych i życia rodzinnego. Podstawa: wykonanie umowy (art. 6 ust. 1 lit. b) oraz Twoja wyraźna zgoda na dane szczególnych kategorii (art. 9 ust. 2 lit. a RODO). W sytuacji bezpośredniego zagrożenia życia — ochrona żywotnych interesów (art. 6 ust. 1 lit. d i art. 9 ust. 2 lit. c RODO), np. przekazanie służbom informacji o Twojej lokalizacji. Okres: zgłoszenie, po którym nie rozpoczęliśmy współpracy — 6 miesięcy od jego wysłania; po rozpoczęciu współpracy — do jej zakończenia i 12 miesięcy po niej (kontynuacja i sesje kontrolne), a następnie dane i notatki usuwamy; dane rozliczeniowe — jak w ust. 2.`,`9. Bezpieczeństwo Serwisu i ochrona Treści cyfrowych — adres IP, dane urządzenia i przeglądarki, dziennik logowań i odtworzeń, identyfikator licencji, znak wodny z e-mailem na filmach i w plikach PDF, limit urządzeń. Podstawa: nasz prawnie uzasadniony interes w zapewnieniu bezpieczeństwa i ochronie praw autorskich (art. 6 ust. 1 lit. f). Okres: dzienniki — 90 dni; identyfikator licencji powiązany z Zamówieniem — jak dane Zamówienia.`,`10. Ustalenie, dochodzenie i obrona roszczeń — Podstawa: prawnie uzasadniony interes (art. 6 ust. 1 lit. f). Okres: do upływu terminów przedawnienia.`,`11. Statystyka i marketing (pliki cookies, piksel Meta) — wyłącznie po Twojej zgodzie w panelu cookies (art. 6 ust. 1 lit. a RODO). Szczegóły w Polityce cookies. W zakresie zbierania i przekazywania danych przez piksel Meta jesteśmy współadministratorem z Meta Platforms Ireland Ltd.; dalsze przetwarzanie przez Meta odbywa się na zasadach Meta.`,`12. Profile w mediach społecznościowych (Facebook, Instagram, WhatsApp) — dane osób, które z nami wchodzą w interakcję (komentarze, wiadomości, statystyki). Podstawa: prawnie uzasadniony interes w prowadzeniu komunikacji (art. 6 ust. 1 lit. f). W zakresie statystyk stron jesteśmy współadministratorem z Meta Platforms Ireland Ltd. Okres: do usunięcia treści lub zgłoszenia sprzeciwu.`,`13. Adres IP przy zapisach i wiadomościach (zapisy na wydarzenia, formularz kontaktowy i inne formularze) — ochrona przed nadużyciami i spamem (np. limit zapisów z jednego adresu). Podstawa: nasz prawnie uzasadniony interes (art. 6 ust. 1 lit. f RODO). Okres: adres IP przechowujemy razem z zapisem lub wiadomością i usuwamy wraz z nimi.`]},{id:`p4`,title:`§4. Czy musisz podać dane?`,body:[`Podanie danych jest dobrowolne, ale bez nich nie założysz Konta, nie złożysz Zamówienia, nie zapiszesz się na Wydarzenie ani nie otrzymasz newslettera. Dane rozliczeniowe są wymagane przepisami podatkowymi.`]},{id:`p5`,title:`§5. Zautomatyzowane decyzje`,body:[`Nie podejmujemy wobec Ciebie decyzji wywołujących skutki prawne wyłącznie w sposób zautomatyzowany. System bezpieczeństwa może automatycznie wstrzymać odtwarzanie wideo na 24 godziny przy podejrzeniu udostępniania Konta — możesz się od tego odwołać, a dalszą decyzję zawsze podejmuje człowiek.`]},{id:`p6`,title:`§6. Odbiorcy danych`,body:[`Twoje dane mogą otrzymać podmioty, które przetwarzają je w naszym imieniu na podstawie umów powierzenia, wyłącznie w zakresie potrzebnym do świadczenia usług:`,`- hosting i platforma Serwisu, w tym analityka odwiedzin (wyłącznie po Twojej zgodzie na cookies analityczne): Base44, Inc. — dostawca platformy, na której działa Serwis (podmiot przetwarzający dane na podstawie umowy powierzenia: base44.com/dpa). Przekazanie danych poza EOG: EU-US Data Privacy Framework albo standardowe klauzule umowne UE;`,`- Supabase, Inc. — dostawca bazy danych (serwery w UE, Frankfurt), podmiot przetwarzający na podstawie umowy powierzenia;`,`- operator płatności: [OPERATOR PŁATNOŚCI], [ADRES OPERATORA] — w zakresie płatności jest odrębnym administratorem;`,`- system mailingowy: [NAZWA, np. MailerLite];`,`- wideokonferencje: Zoom Video Communications, Inc. (USA);`,`- poczta e-mail: [DOSTAWCA POCZTY];`,`- logowanie przez Google (jeśli z niego korzystasz): Google Ireland Ltd.;`,`- Meta Platforms Ireland Ltd. — w zakresie opisanym w §3 ust. 11–12;`,`- biuro rachunkowe: [NAZWA]; kancelaria prawna — w razie potrzeby;`,`- organy publiczne — wyłącznie gdy wymagają tego przepisy.`]},{id:`p7`,title:`§7. Przekazywanie danych poza Europejski Obszar Gospodarczy`,body:[`Niektórzy dostawcy (np. Zoom, Meta, Google, Base44, Inc.) mogą przetwarzać dane poza EOG, w tym w USA lub w Izraelu. Odbywa się to na podstawie decyzji Komisji Europejskiej stwierdzającej odpowiedni stopień ochrony (np. EU–US Data Privacy Framework dla certyfikowanych podmiotów, decyzja dotycząca Izraela) albo standardowych klauzul umownych zatwierdzonych przez Komisję. Kopię zabezpieczeń możesz uzyskać, pisząc do nas.`,`Supabase, Inc. ma siedzibę w USA. Dane w bazie przechowujemy na serwerach w UE (Frankfurt), a ewentualne przekazanie danych do Supabase, Inc. w USA odbywa się na podstawie standardowych klauzul umownych UE lub EU–US Data Privacy Framework.`]},{id:`p8`,title:`§8. Twoje prawa`,body:[`Masz prawo do: dostępu do danych i otrzymania ich kopii, sprostowania, usunięcia, ograniczenia przetwarzania, przenoszenia danych, sprzeciwu wobec przetwarzania opartego na prawnie uzasadnionym interesie (a wobec marketingu — w każdej chwili), wycofania zgody w dowolnym momencie (bez wpływu na zgodność z prawem przetwarzania przed wycofaniem). Część praw zrealizujesz sam(a) w Koncie („Pobierz moje dane”, „Usuń konto”, zgody). Odpowiadamy w ciągu miesiąca. Masz też prawo wnieść skargę do Prezesa Urzędu Ochrony Danych Osobowych (ul. Stawki 2, 00-193 Warszawa, uodo.gov.pl).`]},{id:`p9`,title:`§9. Bezpieczeństwo`,body:[`Stosujemy szyfrowane połączenie (HTTPS), szyfrowanie haseł, kontrolę dostępu, weryfikację dwuetapową dla administratora, dzienniki bezpieczeństwa i ograniczony dostęp do danych. Do treści rozmów mentoringowych dostęp ma wyłącznie prowadzący (Administrator).`]},{id:`p10`,title:`§10. Osoby niepełnoletnie`,body:[`Serwis i usługi są przeznaczone dla osób pełnoletnich. Nie zbieramy świadomie danych osób poniżej 18. roku życia — jeśli dowiemy się o takich danych, usuniemy je.`]},{id:`p11`,title:`§11. Zmiany Polityki`,body:[`O istotnych zmianach poinformujemy na stronie i e-mailem posiadaczy Kont. Poprzednie wersje są dostępne w archiwum.`]}]},u={regulamin:{doc:s,extra:[c]},prywatnosc:{doc:l,extra:[]},cookies:{doc:e,extra:[]}};function d(e,r={},a={},o=null,s=[]){let{doc:c,extra:l}=u[e]||{doc:o||{title:``,sections:[]},extra:s||[]},d=e=>i(n(e,r),a);return{title:c.title,sections:[...c.sections,...l].map(e=>({id:e.id,title:e.title,body:e.body.map(d).filter(Boolean),...e.table?{table:t.map(e=>e.map(d))}:{}}))}}var f=(e,t)=>Object.fromEntries(Object.keys(u).map(n=>[n,d(n,e,t)]));export{c as a,s as i,d as n,a as o,l as r,o as s,f as t};